import{_ as l,l as i,o as a,c as n,v as t,p as d,x as r,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"双向与循环链表","description":"","frontmatter":{"title":"双向与循环链表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dll-circular.md","filePath":"cs/dll-circular.md","lastUpdated":1789023840000}'),h={name:"cs/dll-circular.md"};function u(_,e,m,x,f,A){const o=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="双向与循环链表" tabindex="-1">双向与循环链表 <a class="header-anchor" href="#双向与循环链表" aria-label="Permalink to &quot;双向与循环链表&quot;">​</a></h1><div class="epigraph"><p>再加一条前驱指针，删除就不必先找上一节点；把头尾接成环，空表与单节点用同一套绕接规则。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 1；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/linked-list-locality">上一课</a>以单向链表为主，点名双向用再一个指针换前驱，并强调指针追逐的局部性代价。本课不重讲「插入改两三条边」。缺口是把双向与循环写成可用的表示：已知节点删除 \\(\\Theta(1)\\)、反向遍历、以及哨兵/环降低空表分支。栈课立刻要用「序列的两种表示」；本课把链表这一侧收齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单向删除若只知道被删节点，找不到前驱，必须从头扫，合同退化成 \\(\\Theta(n)\\)。操作系统与内核队列经常「从任意节点摘下」。缺口不是新的 ADT，而是节点 <code>{prev, next, 值}</code> 的不变式：<code>x.next.prev = x</code>（在非空双向表上）。循环：最后一个 <code>next</code> 指向头（或哨兵），避免 <code>tail.next</code> 为空的特殊情况。</p><p>局部性不会因此变好：多一个指针，节点更大，cache 行装更少。本课承认这笔常数，不把链表改回数组。</p><p><span class="marginnote">哨兵节点让空表也有一个真实对象，插入删除少写 <code>if head==null</code>。循环哨兵是 Knuth 卷 1 的常用手法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>双向插入在已知 <code>p</code> 前或后：改四条边。删除 <code>x</code>：<code>x.prev.next = x.next</code>，<code>x.next.prev = x.prev</code>。循环：用哨兵 \\(s\\)，\\(s.next\\) 为真头，\\(s.prev\\) 为真尾；空表 \\(s.next=s.prev=s\\)。</p>',9)),(a(),d(p,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E5%93%A8%E5%85%B5%22%5D%20--%3E%20A%5B%22a%22%5D%0A%20%20A%20--%3E%20B%5B%22b%22%5D%0A%20%20B%20--%3E%20S%0A%20%20S%20-.-%3E%7C%22prev%22%7C%20B%0A%20%20B%20-.-%3E%7C%22prev%22%7C%20A%0A%20%20A%20-.-%3E%7C%22prev%22%7C%20S%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>遍历终止：走回哨兵，不要用空指针当结束（环上没有空）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>合同仍是序列，端点操作与中间操作都可 \\(\\Theta(1)\\) 步（位置已知）。按下标仍 \\(\\Theta(i)\\)。与动态数组分工不变：要随机访问用数组；要任意位置摘挂用双向链。</p><p>循环在轮转调度、约瑟夫环一类「到尾接回头」的轨迹上少一次分支。正确性靠不变式而不是靠「最后一个节点的 next 为 null」这种单向习惯。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 XOR 链表压缩前后指针，不写无锁 CAS 环。也不把循环双向表当成队列的唯一实现——队列课会再用数组环形。跳表的多层前向指针是另一课。</p><p>后课默认：序列的链表表示可以是双向、可循环、可带哨兵。栈把操作收到一端，数组顶或链表头均可。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>双向：已知节点删除 \\(\\Theta(1)\\)，可反向走。</li><li>循环加哨兵：空与非空同一套绕接。</li><li>局部性仍差；栈下一课收窄到 LIFO。</li><li>出处：Knuth, <em>TAOCP</em> 卷 1；Cormen et al. 双向链表。</li></ul>',9))])}const v=l(h,[["render",u]]);export{C as __pageData,v as default};
